# Kaggle kernel for Stage F (audio-LLM judge). Generated by kaggle/build_judge.sh from src/judge.py.
import base64, glob, os, subprocess, sys, time
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "bitsandbytes"], check=True)
import pandas as pd
import torch
from huggingface_hub import snapshot_download

OUT = "/kaggle/working"
MODEL = snapshot_download("Qwen/Qwen2-Audio-7B-Instruct")  # Apache-2.0; downloaded once before workers start
open("/tmp/judge.py", "w").write(base64.b64decode("").decode())
DATA = os.path.dirname(glob.glob("/kaggle/input/**/train.csv", recursive=True)[0])
n = max(1, torch.cuda.device_count())
print("GPUs:", n, [torch.cuda.get_device_name(i) for i in range(n)], flush=True)
t0 = time.time()
procs = [subprocess.Popen([sys.executable, "/tmp/judge.py", "--data", DATA, "--out", OUT, "--model", MODEL,
                           "--nshards", str(n), "--shard", str(i)],
                          env={**os.environ, "CUDA_VISIBLE_DEVICES": str(i)}) for i in range(n)]
codes = [p.wait() for p in procs]
print("worker exit codes:", codes, "| wall time %.0f min" % ((time.time() - t0) / 60), flush=True)
parts = [f"{OUT}/judge.s{i}.csv" for i in range(n) if os.path.exists(f"{OUT}/judge.s{i}.csv")]
df = pd.concat([pd.read_csv(p) for p in parts])
df.to_csv(f"{OUT}/judge.csv", index=False)
print("merged judge rows:", len(df), flush=True)
